const video = $input.first().json;

const videoUrl =
  video.video?.url ||
  video.videoUrl ||
  video.url;

if (!videoUrl) {
  throw new Error("Video URL bulunamadi!");
}

function getNodeData(names) {
  for (const name of names) {
    try {
      return $(name).first().json;
    } catch (e) {}
  }

  throw new Error(
    "Dugum bulunamadi: " + names.join(" / ")
  );
}

const g = getNodeData([
  "17 Gemini JSON dogrula",
  "17 Gemini JSON doğrula"
]);

const rank = getNodeData([
  "14 Gercek trend puanla + top adaylar",
  "14 Gerçek trend puanla + top adaylar"
]);

// Manuel testte preview, otomatikte live
const mode =
  $execution.mode === "production"
    ? "live"
    : "preview";

// Gemini baslik ve aciklama
const title =
  g.youtubeTitle ||
  g.title ||
  "AI Viral Short #shorts";

const baseDescription = String(
  g.youtubeDescription ||
  g.description ||
  "AI-generated visuals."
).trim();

// Hashtagler
const hashtags = Array.isArray(g.hashtags)
  ? g.hashtags
      .map(t => String(t).replace(/^#/, "").trim())
      .filter(Boolean)
  : [];

const missingTags = hashtags.filter(
  t => !baseDescription.includes("#" + t)
);

const description =
  baseDescription +
  (missingTags.length
    ? "\n\n" +
      missingTags.map(t => "#" + t).join(" ")
    : "");

// Kaynak bilgileri
const candidates =
  Array.isArray(rank.candidates)
    ? rank.candidates
    : [];

const candidateUrls = candidates
  .map(c => c.url)
  .filter(Boolean);

const selectedSourceUrl =
  g.selectedSourceUrl ||
  g.sourceUrl ||
  g.sourceUrls?.[0] ||
  candidateUrls[0] ||
  "";

const sourceUrls =
  Array.isArray(g.sourceUrls) &&
  g.sourceUrls.length
    ? g.sourceUrls
    : [
        selectedSourceUrl,
        ...candidateUrls.filter(
          u => u !== selectedSourceUrl
        )
      ].filter(Boolean).slice(0, 3);

// YouTube icin hazir cikti
return [
  {
    json: {
      mode,
      createdAt: new Date().toISOString(),
      videoUrl,
      selectedSourceUrl,
      sourceUrls,
      concept: g.concept || "",
      category: g.category || "",
      why: g.why || "",
      title,
      description,
      hashtags
    }
  }
];

const data = $input.first().json;
const id = data.id || data.uploadId;

if (!id) {
  throw new Error('YouTube video ID bulunamadi');
}

const visibility = data.status?.privacyStatus;

if (visibility !== 'private') {
  throw new Error(
    'Test videosu gizli olarak dogrulanamadi. ' +
    'YouTube Studio uzerinden kontrol et.'
  );
}

const video = $('25 Video + telifsiz metadata').first().json;

// Yayimlanan video fikirlerini kaydet
const store = $getWorkflowStaticData('global');
const history = Array.isArray(store.published)
  ? store.published
  : [];

if (!history.some(item => item.youtubeVideoId === id)) {
  history.push({
    youtubeVideoId: id,
    concept: video.concept,
    title: video.title,
    createdAt: new Date().toISOString()
  });
}

store.published = history.slice(-100);

return [{
  json: {
    status: 'uploaded_private_review',
    youtubeVideoId: id,
    videoUrl: 'https://www.youtube.com/watch?v=' + id,
    concept: video.concept,
    visibility: 'private',
    aiDisclosure: true
  }
}];

const g=$input.first().json;
if(!Array.isArray(g.scenePrompts)||g.scenePrompts.length!==4) throw new Error('Tam olarak 4 sahne gerekli');
const labels=['HOOK','BUILD','TWIST','FINALE'];
return g.scenePrompts.map((p,i)=>({json:{sceneIndex:i,sceneNumber:i+1,sceneLabel:labels[i],videoPrompt:p}}));

const data=$input.first().json;
const url=data.video?.url||data.videoUrl||data.url;
if(typeof url!=='string'||!/^https:\/\//.test(url)) throw new Error('FastWan sahne MP4 URL eksik; yayin durduruldu');
const sceneIndex=$runIndex;
if(sceneIndex<0||sceneIndex>3) throw new Error('Beklenmeyen sahne indeksi: '+sceneIndex);
return [{json:{sceneIndex,sceneNumber:sceneIndex+1,videoUrl:url}}];

const scenes=$input.all().map(x=>x.json).sort((a,b)=>a.sceneIndex-b.sceneIndex);
if(scenes.length!==4||scenes.some((s,i)=>s.sceneIndex!==i||!/^https:\/\//.test(s.videoUrl))) throw new Error('Dort sirali sahne eksiksiz hazir degil; birlestirme ve yayin durduruldu');
const urls=scenes.map(x=>x.videoUrl);
if(new Set(urls).size!==4) throw new Error('Sahne URLleri farkli degil, potansiyel tekrar; islem durduruldu');
return [{json:{video_urls:urls,sceneCount:4,expectedSeconds:20}}];

