const obj=$input.first().json;
const url=obj.video?.url;
if(typeof url!=='string'||!url.startsWith('https://'))throw new Error('Birlestirilmis MP4 bulunamadi');
// Merge endpoint input was 4 separate 5-second clips. Physical duration must still be checked in a live test.
return [{json:obj}];

const scene = $input.first().json;
const prevIndex = scene.sceneIndex - 1;
if (!Number.isInteger(prevIndex) || prevIndex < 0 || prevIndex > 2) throw new Error('Onceki sahne indeksi gecersiz');
let previous;
try {
  const hits = $('24B Sahne sonucu kaydet').all(0, prevIndex);
  previous = hits[0]?.json;
} catch (e) {
  throw new Error('Onceki sahne sonucu bulunamadi. Yeni video uretimi baslatilmadi: ' + e.message);
}
if (!previous || previous.sceneIndex !== prevIndex || !/^https:\/\//.test(previous.videoUrl || '')) {
  throw new Error('Onceki sahne videosu hazir degil. Gorsel sureklilik icin uretim durduruldu.');
}
return [{json:{...scene, previousVideoUrl: previous.videoUrl}}];

const extraction = $input.first().json;
const imageUrl = extraction.images?.[0]?.url || extraction.image?.url;
if (typeof imageUrl !== 'string' || !imageUrl.startsWith('https://')) {
  throw new Error('Son kare gorseli alinamadi. Ucretli video uretimi engellendi.');
}
const sceneIndex = $runIndex + 1;
const scene = $('17B 4 farkli 5sn sahne').all()[sceneIndex]?.json;
if (!scene || scene.sceneIndex !== sceneIndex || !scene.videoPrompt) {
  throw new Error('Yeni sahne promptu ile son kare eslestirilemedi.');
}
return [{json:{...scene, image_url:imageUrl}}];

const result = $input.first().json;
const videoUrl = result.video?.url || result.video_url || result.url;
if(typeof videoUrl !== 'string' || !videoUrl.startsWith('https://')) {
  throw new Error('Sesli video URL bulunamadi; yeniden ses uretimi baslatmadan yaniti kontrol edin.');
}
return [{json:{videoUrl,video:{url:videoUrl},status:'sesli_video_hazir',sourceVideoUrl:$('24K Birlesik MP4 dosyasi dogrula').first().json.video.url}}];
